import 'dart:convert'; import 'package:hive/hive.dart'; import '../models/menu_item_model.dart';
class MenuLocalDataSource { final Box<String> box; static const key='menu'; MenuLocalDataSource({required this.box}); bool get hasData=>box.get(key)!=null; List<MenuItemModel> getMenu(){final raw=box.get(key);if(raw==null)return [];final list=jsonDecode(raw) as List;return list.whereType<Map>().map((e)=>MenuItemModel.fromJson(Map<String,dynamic>.from(e))).toList();} Future<void> saveMenu(List<MenuItemModel> items)=>box.put(key,jsonEncode(items.map((e)=>e.toJson()).toList())); Future<void> clear()=>box.delete(key); }
